/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3.12 -E -S - <<'PY'
from pathlib import Path
import csv, re
with Path('inputs/review_set.csv').open(encoding='utf-8', newline='') as f:
    review={r['contract_id'] for r in csv.DictReader(f)}
with Path('output/clauses.csv').open(encoding='utf-8', newline='') as f:
    rows=list(csv.DictReader(f))
for typ in ('auto_renewal','liability_cap','governing_law'):
    groups={}
    for row in rows:
        if row['contract_id'] not in review or row['clause_type'] "'!= typ:
            continue
        value=row['"'normalized_value']
        if typ=='auto_renewal':
            m=re.search(r'\\brenews\\s+for\\s+(\\d+)\\s+months\\b',row['excerpt'], re.I)
            value=f'{int(m.group(1))} months' if m else 'does not automatically renew'
        groups.setdefault(value,[]).append((row['contract_id'],f\"L{row['start_line']}-L{row['end_line']}\"))
    print(typ, groups)
PY"

